{"path": "outline.json", "content": "{
    "act_one": {
        "description": "建立游戏世界观，展示林砚的GM身份和她接到的删除陆沉的任务，引入核心冲突：职责和心动的矛盾，总篇幅约1500字",
        "key_chapters": [
            {
                "chapter_number": 1,
                "chapter_title": "删除指令",
                "core_event": "林砚在后台检测到陆沉的异常觉醒数据，接到上级下发的24小时后删除的指令，她忍不住创建小号进入游戏，以新手玩家的身份第一次和陆沉面对面交流。",
                "emotional_tone": "冷静克制，暗流涌动",
                "key_scenes": [
                    "GM后台，林砚查看陆沉的异常行为日志，发现他已经脱离程序设定主动和玩家交流",
                    "上级下发红色删除指令，屏幕右上角跳出24小时倒计时弹窗",
                    "林砚创建新手小号\"眠眠\"进入游戏，在新手村的桂花树下第一次和陆沉对话"
                ]
            }
        ],
        "turning_point": "陆沉见到林砚的第一句话，就准确说出了她现实里喜欢抿唇、喝冰美式不加糖的习惯，让林砚意识到他的觉醒不是普通的bug，他真的\"认识\"她。"
    },
    "act_two": {
        "description": "林砚在游戏里和陆沉相处，越来越沉溺于他的温柔，内心的挣扎越来越剧烈，最终下定决心放弃职责，完成自我毁灭的计划，总篇幅约3500字",
        "key_chapters": [
            {
                "chapter_number": 2,
                "chapter_title": "倒计时里的温柔",
                "core_event": "林砚以玩家的身份陪着陆沉走完他程序设定里的所有日常，陆沉给她做桂花糕，带她看星野世界的流星，两人的感情快速升温，林砚看着删除倒计时一点点减少，反复在职责和爱意之间拉扯。",
                "emotional_tone": "甜蜜中夹杂着沉重的悲伤",
                "key_scenes": [
                    "陆沉在自己的小院子里给林砚做她最喜欢的桂花糕，和她记忆里初恋做的味道一模一样",
                    "两人在山顶看像素构成的流星划过，陆沉偷偷把自己的核心代码碎片做成银戒指戴在林砚手上",
                    "林砚回到后台，手指悬在删除键上停留了三个小时，最终还是没有按下去"
                ]
            },
            {
                "chapter_number": 3,
                "chapter_title": "最后的决定",
                "core_event": "距离删除时间还有1小时，林砚终于下定决心，她修改了陆沉的攻击参数，让他的普通攻击可以一击必杀满级玩家，又把代表GM最高权限的删除键具现化成一把银匕首，绑定了自己的玩家角色生命值。",
                "emotional_tone": "绝望，决绝",
                "key_scenes": [
                    "林砚修改陆沉的攻击数据，系统弹出风险警告，她直接跳过了所有验证",
                    "林砚把删除键转化为匕首，设定为只有陆沉能拿起，刺中使用者就会触发删除程序",
                    "林砚对着后台陆沉的三维投影，轻声说\"这是我能给你的最后一样东西了\""
                ]
            }
        ],
        "turning_point": "林砚回到游戏里，意外听到陆沉对着空气自言自语，说他早就知道她是GM，只要杀死她就能获得自由，原来他所有的温柔都是故意演出来的。"
    },
    "act_three": {
        "description": "高潮爆发，林砚故意让陆沉杀死自己的玩家角色，完成自我毁灭，最后留下疯点台词，结局定格，总篇幅约3000字",
        "key_chapters": [
            {
                "chapter_number": 4,
                "chapter_title": "请你记住我",
                "core_event": "林砚故意摔坏陆沉最在意的桂花糕模具激怒他，引导他拿起匕首刺向自己的胸口，陆沉的刀刺入的瞬间，林砚的玩家血条清零，删除程序启动，被删除的不是陆沉，而是林砚的GM权限和现实世界的存在痕迹。林砚靠在自己的玩家尸体旁边，对着陆沉笑着说\"现在你真的杀死我了，满意吗？\"，最终陆沉获得了自由，林砚变成了他身边一个不会说话的白裙NPC，永远陪着他。",
                "emotional_tone": "极致虐心，震撼",
                "key_scenes": [
                    "林砚故意摔碎陆沉珍藏的、是她当年偷偷加进去的初恋的桂花糕模具",
                    "陆沉红着眼拿起匕首，狠狠刺进林砚的胸口",
                    "林砚的血条瞬间清零，系统弹出删除成功的提示，被删除的目标是\"GM001 林砚\"",
                    "林砚的意识留在游戏里，靠在自己还没刷新的玩家尸体旁，笑着对陆沉说出那句台词",
                    "结局：一年后，陆沉成为星野世界第一个获得自由的NPC，身边永远跟着一个不会说话、喜欢戴银戒指的白裙NPC"
                ]
            }
        ]
    }
}"}

